static inline uint16_t blendRGB565(uint16_t bg, uint16_t fg, uint8_t alpha16) {
  if (alpha16 == 0) return bg;
  if (alpha16 >= 15) return fg;
  uint32_t rb = bg & 0xF81F;
  uint32_t g  = bg & 0x07E0;
  uint32_t rb_fg = fg & 0xF81F;
  uint32_t g_fg  = fg & 0x07E0;
  uint32_t rb_out = (rb * (15 - alpha16) + rb_fg * alpha16) / 15;
  uint32_t g_out  = (g  * (15 - alpha16) + g_fg  * alpha16) / 15;
  return (uint16_t)((rb_out & 0xF81F) | (g_out & 0x07E0));
}

